; b03_slot_overrun -- two publishes before Main takes the result: the first one is kept
; Layer-2 conformance test (generated by conformance/make_conformance.py: edit that, not this file).
; Checks: the result slot: Keep Old Drop New, the overrun flag, PERI_RESULT_OVERRUN
; Results go to the result CSRs RES + n (conf_defs.inc); the last write is RES_DONE = 0xA5. Expected values: b03_slot_overrun.expected.csv
.include "conf_defs.inc"
.service SID_FIRST = 1
.service SID_SECOND = 2
.devmap 0, I2C, 0x2C, DEV_SLOT
.main
wait:
    BR.COND PERI_RESULT_OVERRUN, take          ; only once the SECOND publish has found the slot full
    JMP wait
take:
    MOV PERI_RESULT_META[0..0] -> MAIN_SCRATCHPAD[0..0]
    EXEC_CSR WRITE_SP RES + 0, len=1, ptr=0
    MOV PERI_RESULT_SLOT[0..0] -> MAIN_SCRATCHPAD[4..4]
    EXEC_CSR WRITE_SP RES + 1, len=1, ptr=4
    EXEC_CSR WRITE8 RES_DONE, 0xA5          ; the last write: everything above is there
done:
    JMP done
.peri
    EXEC_XFER READ dev=DEV_SLOT, addr=0x01, addrlen=1, ptr=0
    EXEC_PUB service=SID_FIRST, src=0, len=1
    EXEC_XFER READ dev=DEV_SLOT, addr=0x02, addrlen=1, ptr=0
    EXEC_PUB service=SID_SECOND, src=0, len=1  ; the slot still holds the first result: this one is dropped, overrun is set
phalt:
    JMP phalt
